function checkoutUrls(raw) {
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw);
    const out = {};
    Object.keys(parsed).forEach(function (key) {
      const url = String(parsed[key] || "");
      if (/^https:\/\/[^\s"'<>]+$/.test(url)) out[key] = url;
    });
    return out;
  } catch (error) {
    console.error("TOOLKIT_CHECKOUT_URLS is not valid JSON; toolkit buttons fall back to the contact form.");
    return {};
  }
}

function contactHref(topic) {
  return "/contact?topic=" + encodeURIComponent(topic);
}

function catalog(env) {
  const urls = checkoutUrls((env || process.env).TOOLKIT_CHECKOUT_URLS);
  const items = toolkits.map(function (t) {
    return Object.assign({}, t, {
      price: PRICE,
      buyHref: urls[t.slug] || contactHref(t.name + " Toolkit"),
      canBuy: Boolean(urls[t.slug])
    });
  });
  return {
    groups,
    toolkits: items,
    bundle: {
      name: "All 11 toolkits",
      price: BUNDLE_PRICE,
      separately: PRICE * toolkits.length,
      buyHref: urls.bundle || contactHref("All 11 Toolkits bundle"),
      canBuy: Boolean(urls.bundle)
    }
  };
}

module.exports = { catalog, checkoutUrls, PRICE, BUNDLE_PRICE };
